&lt;script type=&quot;text/javascript&quot;&gt;
addEvent(window, &quot;load&quot;, sortables_init);

var SORT_COLUMN_INDEX;

function sortables_init() {
    // Find all tables with class sortable and make them sortable
    if (!document.getElementsByTagName) return;
    tbls = document.getElementsByTagName(&quot;table&quot;);
    for (ti=0;ti&lt;tbls.length;ti++) {
        thisTbl = tbls[ti];
        if (((&#39; &#39;+thisTbl.className+&#39; &#39;).indexOf(&quot;sortable&quot;) != -1) &amp;&amp; (thisTbl.id)) {

            //initTable(thisTbl.id);
            ts_makeSortable(thisTbl);
        }
    }
}

function ts_makeSortable(table) {
    if (table.rows &amp;&amp; table.rows.length &gt; 0) {
        var firstRow = table.rows[0];
    }
    if (!firstRow) return;

    // We have a first row: assume it&#39;s the header, and make its contents clickable links
    for (var i=0;i&lt;firstRow.cells.length;i++) {
        var cell = firstRow.cells[i];
        var txt = ts_getInnerText(cell);
        cell.innerHTML = &#39;&lt;a href=&quot;#&quot; class=&quot;sortheader&quot; onclick=&quot;ts_resortTable(this);return false;&quot;&gt;&#39;+txt+&#39;&lt;span class=&quot;sortarrow&quot;&gt;   &lt;/span&gt;&lt;/a&gt;&#39;;
    }
}

function ts_getInnerText(el) {
	if (typeof el == &quot;string&quot;) return el;
	if (typeof el == &quot;undefined&quot;) { return el };
	if (el.innerHTML) return el.innerHTML;	//Not needed but it is faster
	var str = &quot;&quot;;

	var cs = el.childNodes;
	var l = cs.length;
	for (var i = 0; i &lt; l; i++) {
		switch (cs[i].nodeType) {
			case 1: //ELEMENT_NODE
				str += ts_getInnerText(cs[i]);
				break;
			case 3:	//TEXT_NODE
				str += cs[i].nodeValue;
				break;
		}
	}
	return str;
}

function ts_resortTable(lnk) {
    // get the span
    var span;
    for (var ci=0;ci&lt;lnk.childNodes.length;ci++) {
        if (lnk.childNodes[ci].tagName &amp;&amp; lnk.childNodes[ci].tagName.toLowerCase() == &#39;span&#39;) span = lnk.childNodes[ci];
    }
    var spantext = ts_getInnerText(span);
    var td = lnk.parentNode;
    var column = td.cellIndex;
    var table = getParent(td,&#39;TABLE&#39;);

	var startline=1;
	if (document.getElementById(table.id+&#39;_tbody&#39;)) {
		startline = 0;
		table = document.getElementById(table.id+&#39;_tbody&#39;);
	}



    // Work out a type for the column
    if (table.rows.length &lt;= 1) return;
    var itm = ts_getInnerText(table.rows[1].cells[column]);
    sortfn = ts_sort_caseinsensitive;
    if (itm.match(/^\d\d[\/-]\d\d[\/-]\d\d\d\d$/)) sortfn = ts_sort_date;
    if (itm.match(/^\d\d[\/-]\d\d[\/-]\d\d$/)) sortfn = ts_sort_date;
    if (itm.match(/^[&#163;$]/)) sortfn = ts_sort_currency;
    if (itm.match(/^[\d\.]+$/)) sortfn = ts_sort_numeric;
    SORT_COLUMN_INDEX = column;
    var firstRow = new Array();
    var newRows = new Array();
    for (i=0;i&lt;table.rows[0].length;i++) { firstRow[i] = table.rows[0][i]; }
    for (j=startline;j&lt;table.rows.length;j++) { newRows[j-startline] = table.rows[j]; }

    newRows.sort(sortfn);

    if (span.getAttribute(&quot;sortdir&quot;) == &#39;down&#39;) {
        ARROW = &#39;  ?&#39;;
        newRows.reverse();
        span.setAttribute(&#39;sortdir&#39;,&#39;up&#39;);
    } else {
        ARROW = &#39;  ?&#39;;
        span.setAttribute(&#39;sortdir&#39;,&#39;down&#39;);
    }

    // We appendChild rows that already exist to the tbody, so it moves them rather than creating new ones
    // don&#39;t do sortbottom rows
    for (i=0;i&lt;newRows.length;i++) { if (!newRows[i].className || (newRows[i].className &amp;&amp; (newRows[i].className.indexOf(&#39;sortbottom&#39;) == -1))) table.tBodies[0].appendChild(newRows[i]);}
    // do sortbottom rows only
    for (i=0;i&lt;newRows.length;i++) { if (newRows[i].className &amp;&amp; (newRows[i].className.indexOf(&#39;sortbottom&#39;) != -1)) table.tBodies[0].appendChild(newRows[i]);}

    // Delete any other arrows there may be showing
    var allspans = document.getElementsByTagName(&quot;span&quot;);
    for (var ci=0;ci&lt;allspans.length;ci++) {
        if (allspans[ci].className == &#39;sortarrow&#39;) {
            if (getParent(allspans[ci],&quot;table&quot;) == getParent(lnk,&quot;table&quot;)) { // in the same table as us?
                allspans[ci].innerHTML = &#39;   &#39;;
            }
        }
    }

    span.innerHTML = ARROW;
}

function getParent(el, pTagName) {
	if (el == null) return null;
	else if (el.nodeType == 1 &amp;&amp; el.tagName.toLowerCase() == pTagName.toLowerCase())	// Gecko bug, supposed to be uppercase
		return el;
	else
		return getParent(el.parentNode, pTagName);
}
function ts_sort_date(a,b) {
    // y2k notes: two digit years less than 50 are treated as 20XX, greater than 50 are treated as 19XX
    aa = ts_getInnerText(a.cells[SORT_COLUMN_INDEX]);
    bb = ts_getInnerText(b.cells[SORT_COLUMN_INDEX]);
    if (aa.length == 10) {
        dt1 = aa.substr(6,4)+aa.substr(3,2)+aa.substr(0,2);
    } else {
        yr = aa.substr(6,2);
        if (parseInt(yr) &lt; 50) { yr = &#39;20&#39;+yr; } else { yr = &#39;19&#39;+yr; }
        dt1 = yr+aa.substr(3,2)+aa.substr(0,2);
    }
    if (bb.length == 10) {
        dt2 = bb.substr(6,4)+bb.substr(3,2)+bb.substr(0,2);
    } else {
        yr = bb.substr(6,2);
        if (parseInt(yr) &lt; 50) { yr = &#39;20&#39;+yr; } else { yr = &#39;19&#39;+yr; }
        dt2 = yr+bb.substr(3,2)+bb.substr(0,2);
    }
    if (dt1==dt2) return 0;
    if (dt1&lt;dt2) return -1;
    return 1;
}

function ts_sort_currency(a,b) { 
    aa = ts_getInnerText(a.cells[SORT_COLUMN_INDEX]).replace(/[^0-9.]/g,&#39;&#39;);
    bb = ts_getInnerText(b.cells[SORT_COLUMN_INDEX]).replace(/[^0-9.]/g,&#39;&#39;);
    return parseFloat(aa) - parseFloat(bb);
}

function ts_sort_numeric(a,b) { 

    aa = parseFloat(ts_getInnerText(a.cells[SORT_COLUMN_INDEX]));
    if (isNaN(aa)) aa = -1;
    bb = parseFloat(ts_getInnerText(b.cells[SORT_COLUMN_INDEX])); 
    if (isNaN(bb)) bb = -1;
    return aa-bb;
}

function removeAccents(s) {
    var r = s.toLowerCase();
    r = r.replace(new RegExp(/\s/g),&quot;&quot;);
    r = r.replace(new RegExp(/[&#224;&#225;&#226;&#227;&#228;&#229;]/g),&quot;a&quot;);
    r = r.replace(new RegExp(/&#230;/g),&quot;ae&quot;);
    r = r.replace(new RegExp(/&#231;/g),&quot;c&quot;);
    r = r.replace(new RegExp(/[&#232;&#233;&#234;&#235;]/g),&quot;e&quot;);
    r = r.replace(new RegExp(/[&#236;&#237;&#238;&#239;]/g),&quot;i&quot;);
    r = r.replace(new RegExp(/&#241;/g),&quot;n&quot;);                
    r = r.replace(new RegExp(/[&#242;&#243;&#244;&#245;&#246;]/g),&quot;o&quot;);
    r = r.replace(new RegExp(/œ/g),&quot;oe&quot;);
    r = r.replace(new RegExp(/[&#249;&#250;&#251;&#252;]/g),&quot;u&quot;);
    r = r.replace(new RegExp(/[&#253;&#255;]/g),&quot;y&quot;);
    r = r.replace(new RegExp(/\W/g),&quot;&quot;);
    return r;
}
function ts_sort_caseinsensitive(a,b) {
    aa = ts_getInnerText(a.cells[SORT_COLUMN_INDEX]).toLowerCase();
    bb = ts_getInnerText(b.cells[SORT_COLUMN_INDEX]).toLowerCase();
    aa = removeAccents(aa);
    bb = removeAccents(bb);
    if (aa==bb) return 0;
    if (aa&lt;bb) return -1;
    return 1;
}

function ts_sort_default(a,b) {

    aa = ts_getInnerText(a.cells[SORT_COLUMN_INDEX]);
    bb = ts_getInnerText(b.cells[SORT_COLUMN_INDEX]);
    if (aa==bb) return 0;
    if (aa&lt;bb) return -1;
    return 1;
}


function addEvent(elm, evType, fn, useCapture)
// addEvent and removeEvent
// cross-browser event handling for IE5+,  NS6 and Mozilla
// By Scott Andrew
{
  if (elm.addEventListener){
    elm.addEventListener(evType, fn, useCapture);
    return true;
  } else if (elm.attachEvent){
    var r = elm.attachEvent(&quot;on&quot;+evType, fn);
    return r;
  } else {
    alert(&quot;Handler could not be removed&quot;);
  }
}
